create table public.community_comments (id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete set null,author_name text not null,badge text not null default 'Nuevo analista',asset text not null,body text not null,useful_count integer not null default 0,score numeric(2,1),status text not null default 'published' check(status in('published','reviewed','hidden')),created_at timestamptz not null default now(),reviewed_at timestamptz,reviewed_by uuid references auth.users(id));
alter table public.community_comments enable row level security;
create policy "public_read_visible_comments" on public.community_comments for select to anon,authenticated using(status<>'hidden' or(select private.is_admin()));
create policy "users_insert_own_comments" on public.community_comments for insert to authenticated with check((select auth.uid())=user_id and status='published');
create policy "admins_update_comments" on public.community_comments for update to authenticated using((select private.is_admin())) with check((select private.is_admin()));
grant select on public.community_comments to anon; grant select,insert,update on public.community_comments to authenticated;
insert into public.community_comments(author_name,badge,asset,body,useful_count,score,status) values ('Lucía Quant','Analista destacada','BTC','La señal mejoró cuando el volumen confirmó la ruptura. Practicaría con una posición pequeña y un límite de pérdida.',48,4.9,'published'),('Marco V.','Pulso experto','USD/BOB','Conviene comparar el oficial con P2P y no mezclarlos: responden a mercados y condiciones diferentes.',35,4.7,'published'),('Ana Crypto','Comentario útil','ETH','La tendencia es alcista, pero esperaría el cierre de la vela antes de entrar para evitar una falsa ruptura.',29,4.6,'published');
create table public.site_visits(id bigint generated always as identity primary key,visitor_id uuid not null,session_id uuid not null,path text not null,device text not null check(device in('mobile','tablet','desktop')),visited_at timestamptz not null default now(),unique(session_id,path));
alter table public.site_visits enable row level security; create policy "admins_read_visits" on public.site_visits for select to authenticated using((select private.is_admin())); grant select on public.site_visits to authenticated;
create index site_visits_visited_at_idx on public.site_visits(visited_at desc); create index site_visits_visitor_id_idx on public.site_visits(visitor_id);
